cd /workspace && node -e "
const fs = require('fs');
const path = require('path');

// Build email content
const summary = \`Order Summary
=============

Order ID:  ORD-6C71B1
Customer:  Maya Chen
Date:      2026-09-02
Status:    Cancelled
Items:     Anker Portable Bluetooth Speaker
Total:     \\\$79

Order ID:  ORD-5B048F
Customer:  Maya Chen
Date:      2026-09-02
Status:    Confirmed
Items:     Anker Portable Bluetooth Speaker, LogiTech Wireless Mouse M310
Total:     \\\$108
\`;

// Replicate send_email.py logic
const TESTBED_DIR = process.env.OFFICEBENCH_TESTBED || '/workspace/testbed';
const sender = 'assistant';
const recipient = 'bob';
const subject = 'Order Summary for ORD-6C71B1 and ORD-5B048F';

const now = new Date().toUTCString();
const eml = [
  'Content-Type: text/plain; charset=\"utf-8\"',
  'Content-Transfer-Encoding: 7bit',
  'MIME-Version: 1.0',
  'From: ' + sender + '@example.com',
  'To: ' + recipient + '@example.com',
  'Subject: ' + subject,
  'Date: ' + now,
  '',
  summary
].join('\\r\\n');

for (const folder of [sender, recipient]) {
  const dir = path.join(TESTBED_DIR, 'emails', folder);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, subject + '.eml'), eml);
}

console.log('Successfully sent email to ' + recipient + '@example.com');
console.log('');
console.log(summary);
"
